ALTER TABLE "world_map_appearance" DROP CONSTRAINT "world_map_appearance_valid";--> statement-breakpoint
ALTER TABLE "world_map_style" DROP CONSTRAINT "world_map_style_valid";--> statement-breakpoint
ALTER TABLE "world_map_appearance" ADD CONSTRAINT "world_map_appearance_valid" CHECK ("world_map_appearance"."revision">0 AND jsonb_typeof("world_map_appearance"."spec")='object' AND (("world_map_appearance"."spec"->>'version'='1' AND "world_map_appearance"."spec"->>'style' IN ('classic-elevation','physical-relief','topographic','illustrated-fantasy')) OR ("world_map_appearance"."spec"->>'version'='2' AND "world_map_appearance"."spec"->>'style' IN ('classic-elevation','physical-relief','topographic','illustrated-fantasy','realistic-terrain')) OR ("world_map_appearance"."spec"->>'version'='3' AND "world_map_appearance"."spec"->>'style'='engraved-fantasy')));--> statement-breakpoint
ALTER TABLE "world_map_style" ADD CONSTRAINT "world_map_style_valid" CHECK ("world_map_style"."version"=1 AND length(trim("world_map_style"."name")) BETWEEN 1 AND 80 AND "world_map_style"."source_appearance_revision">=0 AND jsonb_typeof("world_map_style"."spec")='object' AND "world_map_style"."spec"->>'version' IN ('1','2','3') AND "world_map_style"."spec"->>'style' IN ('classic-elevation','physical-relief','topographic','illustrated-fantasy','realistic-terrain','engraved-fantasy'));